 static final class Site {String name;List<StructurePiece> pieces=new ArrayList<>();List<RandomizableContainerBlockEntity> containers=new ArrayList<>();UUID id;boolean spring;Site(String n){name=n;id=UUID.nameUUIDFromBytes(n.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 static final Set<String> stackChecks=new HashSet<>();static long stackAssertions;
 static void check(boolean ok,String what){if(what.startsWith("legal native stack")){stackAssertions++;if(ok&&!stackChecks.add(what))return;}checks.add(Map.of("site",current,"test",what,"result",ok?"PASS":"FAIL"));if(!ok)throw new IllegalStateException(current+": "+what);}
 static ResourceLocation id(String s){return ResourceLocation.fromNamespaceAndPath("slavicmyths",s);}
